                    { -5, "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #2c3e50;'>Payment Received</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>We have successfully received your payment. It is currently under verification.</p><div style='background: #f8f9fa; padding: 15px; border-radius: 5px;'><p><strong>Amount:</strong> {{Amount}} BDT</p><p><strong>Transaction ID:</strong> {{TrxID}}</p></div><p>You will be notified once the payment is verified.</p></div>", "PAYMENT_RECEIVED", "Payment received acknowledgment", new DateTime(2026, 3, 20, 23, 48, 9, 136, DateTimeKind.Utc).AddTicks(6545), "Payment Received: {{Amount}} BDT", "['FullName', 'Amount', 'TrxID']" },
                    { -4, "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #e74c3c;'>Application Status Update</h2><p>Dear <strong>{{FullName}}</strong>,</p><p>Thank you for your interest in the GHC Alumni Association. After reviewing your application, we regret to inform you that we cannot approve it at this time.</p><div style='background: #fdf2f2; padding: 15px; border-radius: 5px; border-left: 5px solid #e74c3c;'><p><strong>Reason:</strong> {{Reason}}</p></div><p>If you believe this is an error, please contact the association office.</p></div>", "APPLICATION_REJECTED", "Application rejection email", new DateTime(2026, 3, 20, 23, 48, 9, 136, DateTimeKind.Utc).AddTicks(6477), "Update on your GHCAA Membership Application", "['FullName', 'Reason']" },
                    { -3, "<div style='font-family: sans-serif; padding: 20px; border: 1px solid #eee; border-radius: 10px; max-width: 600px;'><h2 style='color: #c5a059;'>Password Reset</h2><p>Hello <strong>{{FullName}}</strong>,</p><p>An administrator has initiated a password reset for your GHCAA account. Click below to set a new password — the link is valid for 24 hours.</p><div style='text-align: center; margin: 30px 0;'><a href='{{ResetUrl}}' style='background: #111; color: #c5a059; padding: 12px 30px; text-decoration: none; border-radius: 8px; font-weight: 800; display: inline-block; border: 1px solid #c5a059;'>Reset My Password</a></div><p style='color: #666; font-size: 0.9rem;'>If you did not request this, please ignore this email.</p></div>", "PASSWORD_RESET", "Password reset email", new DateTime(2026, 3, 20, 23, 48, 9, 136, DateTimeKind.Utc).AddTicks(4342), "GHCAA Account Password Reset", "['FullName', 'ResetUrl']" },
